from __future__ import annotations

import base64
import zlib
from pathlib import Path

PAYLOAD = ""

raw = zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
for path in (
    Path("data/course_redevelopment/laboratorio-biomecanica/units/unit-06.json"),
    Path("data/generated_units/laboratorio-biomecanica/unit-06.json"),
):
    path.write_text(raw + "\n", encoding="utf-8")
